UPDATE MST_TRADE_CALENDAR as A, ( select TRADE_CALENDAR_ID, CALENDAR_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME from ( select TEMP.* from (
SELECT #{item.tradeCalendarId,jdbcType=CHAR} TRADE_CALENDAR_ID, #{item.calendarId,jdbcType=VARCHAR} CALENDAR_ID, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME FROM dual
) TEMP ) de ) AS B set A.CREATE_USER = B.CREATE_USER, A.CREATE_DEPT = B.CREATE_DEPT, A.CREATE_TIME = B.CREATE_TIME, A.UPDATE_USER = B.UPDATE_USER, A.UPDATE_TIME = B.UPDATE_TIME where A.TRADE_CALENDAR_ID = B.TRADE_CALENDAR_ID; insert into MST_TRADE_CALENDAR(TRADE_CALENDAR_ID, CALENDAR_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME) select TRADE_CALENDAR_ID, CALENDAR_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME from ( select TEMP.* from (
SELECT #{item.tradeCalendarId,jdbcType=CHAR} TRADE_CALENDAR_ID, #{item.calendarId,jdbcType=VARCHAR} CALENDAR_ID, #{item.createUser,jdbcType=VARCHAR} CREATE_USER, #{item.createDept,jdbcType=VARCHAR} CREATE_DEPT, #{item.createTime,jdbcType=TIMESTAMP} CREATE_TIME, #{item.updateUser,jdbcType=VARCHAR} UPDATE_USER, #{item.updateTime,jdbcType=TIMESTAMP} UPDATE_TIME FROM dual
) TEMP where not exists (select 1 from MST_TRADE_CALENDAR CII where CII.TRADE_CALENDAR_ID = TEMP.TRADE_CALENDAR_ID) ) de ;
